-- ===== PRD_000198 피크닉매트 =====
DELETE FROM t_prc_component_prices WHERE comp_cd='COMP_GOODS_FIXED_SIZ' AND apply_ymd='2026-07-03' AND siz_cd IN ('SIZ_000399','SIZ_000402');

-- ===== PRD_000217 만년스탬프 =====
DELETE FROM t_prc_component_prices WHERE comp_cd='COMP_GOODS_FIXED_SIZ' AND apply_ymd='2026-07-03' AND siz_cd IN ('SIZ_000419','SIZ_000420','SIZ_000421','SIZ_000422','SIZ_000423','SIZ_000424','SIZ_000425');

